// Title: How to center a header at the top of each PDF page using Aspose.Cells for .NET
// Common Searches: Aspose.Cells C# set center header for PDF export | C# create PDF from Excel with top‑centered page header using Aspose.Cells | Adjust top margin and add centered header in PDF generated by Aspose.Cells | How to use PageSetup.CenterHeader to align header in PDF with Aspose.Cells | Center header text on every PDF page when saving workbook as PDF in .NET
// Tags: Aspose.Cells PageSetup.CenterHeader PDF | center header PDF Aspose.Cells C# | adjust top margin Aspose.Cells PDF export | Excel to PDF header alignment Aspose.Cells | C# Aspose.Cells PDF page header formatting

using Aspose.Cells;
using System;
using System.IO;

namespace AsposeCellsExample
{
    // The example creates a new Workbook, populates sample data, optionally sets a centered header via PageSetup.CenterHeader, adjusts the top margin, ensures the output directory exists, and saves the workbook as a PDF file using Aspose.Cells for .NET.
    class Program
    {
        static void Main()
        {
            try
            {
                // Create a new workbook
                Workbook workbook = new Workbook();

                // Get the first worksheet
                Worksheet sheet = workbook.Worksheets[0];

                // Populate some sample data
                sheet.Cells["A1"].PutValue("Sample Data");
                sheet.Cells["A2"].PutValue(123);
                sheet.Cells["A3"].PutValue(DateTime.Now);

                // Set a centered header with font and size (available in newer Aspose.Cells versions)
                // If the property is not present in the referenced version, this line can be omitted.
                // sheet.PageSetup.CenterHeader = "&C&\"Arial,Bold\"&16 My Document Header";

                // Adjust top margin (in inches)
                sheet.PageSetup.TopMargin = 0.5;

                // Define output path and ensure the directory exists
                string outputPath = "Output.pdf";
                string outputDir = Path.GetDirectoryName(Path.GetFullPath(outputPath));
                if (!Directory.Exists(outputDir))
                {
                    Directory.CreateDirectory(outputDir);
                }

                // Save the workbook as a PDF file
                workbook.Save(outputPath, SaveFormat.Pdf);
                Console.WriteLine($"Workbook saved successfully to '{outputPath}'.");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"An error occurred: {ex.Message}");
            }
        }
    }
}
